@Command([EditDocument];"1");

@If (DateRequired= ""; @Return(@Do(@Command([EditGotoField];"DateRequired") ;@Prompt([Ok];"Missing Value"; "Please specify when the driver is required!")));"");
@If (tTime= ""; @Return(@Do(@Command([EditGotoField];"tTime") ;@Prompt([Ok];"Missing Value"; "Please select the Time  before proceeding!")));"");
@If (tTime_1= ""; @Return(@Do(@Command([EditGotoField];"tTime_1") ;@Prompt([Ok];"Missing Value"; "Please select the Time  before proceeding!")));"");
@If (Venue= ""; @Return(@Do(@Command([EditGotoField];"Venue") ;@Prompt([Ok];"Missing Value"; "You forgot to select the Venue!")));"");

FIELD Requestor := @V3UserName;
FIELD DateRequested := @Today;
FIELD CA := "Submitted";

@Command([FileSave]);

@MailSend(IOIADMIN;defcc:cc;NULL;"New Driver Arrangement Requisition  - " + RDARNo;NULL;"Please click the doclink  ---> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If (AdminName= ""; @Return(@Do(@Command([EditGotoField];"AdminName") ;@Prompt([Ok];"Missing Value"; "Please state your name!")));"");
@If (Status= ""; @Return(@Do(@Command([EditGotoField];"Status") ;@Prompt([Ok];"Missing Value"; "Please select the status before proceeding!")));"");
@If (DriverName= ""; @Return(@Do(@Command([EditGotoField];"DriverName") ;@Prompt([Ok];"Missing Value"; "Please state Driver's name!")));"");
@If (DriverNo= ""; @Return(@Do(@Command([EditGotoField];"DriverNo") ;@Prompt([Ok];"Missing Value"; "Please state Driver's contact number before proceeding!")));"");
@If (VehicleNo= ""; @Return(@Do(@Command([EditGotoField];"VehicleNo") ;@Prompt([Ok];"Missing Value"; "Please insert the Vehicle number before proceeding!")));"");

FIELD AdminStaff := @V3UserName;
FIELD DateCompleted :=@Today;
FIELD CA := Status;

@Command([FileSave]);

@MailSend(Requestor;defcc:cc;NULL;"Driver Arrangement Requisition is " + Status + " - " + RDARNo;NULL;"Please click the doclink  ---> ";[IncludeDoclink]);

